from dataclasses import dataclass, field

@dataclass
class LineItem:
    name: str
    price: float
    qty: int = 1

    def subtotal(self) -> float:
        return self.price * self.qty

@dataclass
class Invoice:
    customer: str
    items: list[LineItem] = field(default_factory=list)

    def add(self, item: LineItem) -> None:
        self.items.append(item)

    def total(self, gst_rate: float = 0.18) -> float:
        return round(sum(i.subtotal() for i in self.items) * (1 + gst_rate), 2)

inv = Invoice("Riya")
inv.add(LineItem("Masala chai", 20.0, 3))
print(inv.total())

