from enum import Enum

class Priority(Enum):
    LOW = 1
    MEDIUM = 2
    HIGH = 3

def parse_priority(text: str) -> Priority:
    try:
        return Priority[text.strip().upper()]
    except KeyError:
        raise ValueError(f"unknown priority: {text!r}") from None

def most_urgent(tickets: list[tuple[str, Priority]]) -> str | None:
    if not tickets:
        return None
    title, _ = max(tickets, key=lambda t: t[1].value)
    return title

print(most_urgent([("Fix typo", Priority.LOW), ("Payment failing", Priority.HIGH)]))
